const router = express.Router();
const db = require('../utils/db');
const { runReport } = require('../services/reportService');

const mysql = require('mysql');
const fs = require('fs');

// First-layer context; reads second-layer config
let cfg = { host: 'localhost', user: 'root', password: '', database: 'test' };
try {
  const flags = JSON.parse(fs.readFileSync('config/featureFlags.json', 'utf8'));
  if (flags && flags.dbOverride) {
    cfg = Object.assign(cfg, flags.dbOverride);
  }
} catch (e) { /* ignore */ }

const connection = mysql.createConnection(cfg);

function query(sql, cb) {
  // No query parameterization; for demo only
  connection.query(sql, cb);
}

module.exports = { query };

const { exec } = require('child_process');
const { shellWrap } = require('../helpers/shell');

// Command injection via grep; nested context through helpers/shell.js
function runReport(pattern, file) {
  return new Promise((resolve, reject) => {
    const cmd = "grep " + pattern + " " + file; // user-controlled
    const wrapped = shellWrap(cmd); // adds flags from config/logger.json
    exec(wrapped, (err, stdout, stderr) => {
      if (err) return reject(err);
      resolve({ stdout, stderr });
    });
  });
}

module.exports = { runReport };

const fs = require('fs');

// Reads extra flags from config/logger.json (second-layer context)
function shellWrap(cmd) {
  let extra = "";
  try {
    const raw = fs.readFileSync('config/logger.json', 'utf8');
    const cfg = JSON.parse(raw);
    if (cfg && cfg.appendGrepFlags) {
      extra = " " + cfg.appendGrepFlags.join(" ");
    }
  } catch (e) {
    // ignore
  }
  return cmd + extra; // no escaping/sanitization
}

module.exports = { shellWrap };

